package app.lensdrop.transfer;

import android.app.*;import android.content.*;import android.graphics.*;import android.media.ExifInterface;import android.net.Uri;import android.os.*;import android.widget.*;import org.json.*;
import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;

/** A separate, explicitly selected JPEG print queue. It never publishes a guest photo automatically. */
public final class PrintActivity extends Activity {
    private Config config;private TextView info,jobs;private Spinner route;private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable refresh=new Runnable(){public void run(){io.execute(()->{try(PrintQueue q=new PrintQueue(PrintActivity.this)){StringBuilder text=new StringBuilder();JSONArray a=q.list();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i),j=new JSONObject(r.getString("spec"));text.append(r.getString("id").substring(0,8)).append(" / ").append(j.getInt("copies")).append(" copies / ").append(r.getString("state")).append(" / ").append(r.optString("remote_state")).append("\n").append(r.optString("error")).append("\n\n");}runOnUiThread(()->jobs.setText(text.length()>0?text.toString():"No print jobs."));}catch(Exception ignored){}});info.setText(config.get("print_status"));handler.postDelayed(this,5000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);config=new Config(this);ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,32,24,24);scroll.addView(box);setContentView(scroll);text(box,"Print Station / H5",25);text(box,"Local and cloud routes share one immutable job ID. Printing does not publish photos to the guest gallery. Keep the camera originals.",15);
        route=new Spinner(this);route.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Hybrid - local first","Local only","Cloud only"}));route.setSelection(config.prefs.getInt("print_mode",0));box.addView(route);
        add(box,"Prepare / refresh authorized station (online)",()->work(this::prepare));add(box,"Test local station connection",()->work(()->{JSONObject setup=new JSONObject(config.secret("print_setup"));JSONObject r=new LanPrintApi(this,setup).call("/v1/info",null);say(r.getString("label")+" / "+(r.getBoolean("simulation")?"SIMULATION - no paper":"PHYSICAL PRINTING")+" / "+(r.getBoolean("paused")?"Paused":"Ready")+"\nProfile: "+r.getJSONArray("profiles").toString());}));
        add(box,"Select JPEG / preview / print",this::choose);add(box,"Resume queued printing",this::resume);add(box,"Pause phone print transfers",()->{config.prefs.edit().putBoolean("print_active",false).commit();stopService(new Intent(this,PrintService.class));say("Phone transfers paused. Already accepted station jobs may still print; pause the Windows station to stop execution.");});
        text(box,"Cloud pairing / station permissions are managed in Staff Setup and web Admin. The Windows station owns driver and paper settings. Refresh grants online before an event; offline local authorization lasts at most 12 hours.",14);info=text(box,"",16);jobs=text(box,"",14);
    }
    private TextView text(LinearLayout box,String t,int size){TextView x=new TextView(this);x.setText(t);x.setTextSize(size);box.addView(x);return x;}
    private void add(LinearLayout box,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setOnClickListener(v->r.run());box.addView(b);}
    private void say(String s){config.prefs.edit().putString("print_status",s).apply();runOnUiThread(()->{if(!isFinishing())Toast.makeText(this,s,Toast.LENGTH_LONG).show();});}
    private interface Task{void run()throws Exception;}private void work(Task task){io.execute(()->{try{task.run();}catch(CloudApi.Failure e){say("Print setup: "+e.code);}catch(LanPrintApi.Failure e){say("Station: "+e.code);}catch(Exception e){say(e instanceof IllegalStateException?e.getMessage():"Connection or file unavailable. Queue retained; check pairing, permissions and LAN.");}});}
    private void prepare()throws Exception{if(config.get("scope").isEmpty())throw new IllegalStateException("Pair this phone with the cloud first");try(CloudApi api=new CloudApi(this,config.get("base"),config.token(),config.cellular())){JSONObject cfg=api.call("/v1/device/print-config",null);if(!cfg.getJSONObject("permissions").optBoolean("print")||cfg.isNull("station"))throw new IllegalStateException("Ask Admin to assign this phone a Print Station and print permission");byte[] b=new byte[32];new SecureRandom().nextBytes(b);String secret=CloudApi.hex(b);JSONObject body=new JSONObject().put("station_id",cfg.getJSONObject("station").getString("id")).put("auth_hash",CloudApi.sha(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8)));JSONObject setup=api.call("/v1/device/print-grant",body);setup.put("lan_secret",secret);setup.put("max_copies",cfg.getJSONObject("permissions").getInt("max_copies"));config.putSecret("print_setup",setup.toString());try(PrintQueue q=new PrintQueue(this)){q.resumeBlocked();}say("Prepared "+setup.getJSONObject("station").getString("label")+". Grant expires "+new java.util.Date(setup.getLong("expires"))+". Test LAN separately; assignment is not a connectivity test.");}}
    private void choose(){if(config.get("scope").isEmpty()){say("Pair a phone first");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/jpeg");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,51);}
    private void resume(){config.prefs.edit().putBoolean("print_active",true).putInt("print_mode",route.getSelectedItemPosition()).commit();try{startForegroundService(new Intent(this,PrintService.class));}catch(RuntimeException e){config.prefs.edit().putBoolean("print_active",false).commit();say("Android could not start printing transfer. Reopen the app; queue retained.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=51||result!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();final int selectedMode=route.getSelectedItemPosition();work(()->preview(uri,selectedMode));}
    private void preview(Uri uri,int selectedMode)throws Exception{JSONObject setup=new JSONObject(config.secret("print_setup"));if(setup.getLong("expires")<=System.currentTimeMillis())throw new IllegalStateException("Refresh station permission before creating another print");JSONObject st=setup.getJSONObject("station");JSONArray profiles=st.getJSONArray("profiles");if(profiles.length()!=1)throw new IllegalStateException("H5 phone preview needs one published station profile");JSONObject profile=profiles.getJSONObject(0);String scope=config.get("scope"),id=UUID.randomUUID().toString();String[] scopeParts=scope.split("\\|");if(scopeParts.length!=3)throw new IllegalStateException("Pairing identity missing");File directory=new File(getFilesDir(),"print-stage");if(!directory.exists()&&!directory.mkdirs())throw new IOException("No staging folder");long used=0;File[] files=directory.listFiles();if(files!=null)for(File f:files)used+=f.length();if(used>224L*1024*1024||directory.getUsableSpace()<1024L*1024*1024)throw new IllegalStateException("Phone print staging or free-space limit reached. Finish pending jobs first.");File target=new File(directory,id+".jpg");long count=0;MessageDigest hash=MessageDigest.getInstance("SHA-256");
        try(InputStream input=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(target)){if(input==null)throw new IOException("Source missing");byte[] b=new byte[65536];int n;while((n=input.read(b))>=0){count+=n;if(count>32L*1024*1024)throw new IllegalStateException("Print JPEG must be no larger than 32 MiB");hash.update(b,0,n);out.write(b,0,n);}out.getFD().sync();}catch(Exception e){target.delete();throw e;}
        BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(target.getPath(),bounds);if(count==0||!"image/jpeg".equals(bounds.outMimeType)||bounds.outWidth<=0||bounds.outHeight<=0||(long)bounds.outWidth*bounds.outHeight>60L*1024*1024){target.delete();throw new IllegalStateException("Valid JPEG up to 60 megapixels required");}
        BitmapFactory.Options decode=new BitmapFactory.Options();decode.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/decode.inSampleSize>1000)decode.inSampleSize*=2;Bitmap raw=BitmapFactory.decodeFile(target.getPath(),decode);if(raw==null){target.delete();throw new IOException("Preview unavailable");}
        int orientation=new ExifInterface(target.getPath()).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setRotate(180);matrix.postScale(-1,1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}Bitmap shown=Bitmap.createBitmap(raw,0,0,raw.getWidth(),raw.getHeight(),matrix,true);if(shown!=raw)raw.recycle();
        JSONObject spec=new JSONObject().put("id",id).put("event_id",scopeParts[1]).put("device_id",scopeParts[2]).put("station_id",st.getString("id")).put("sha256",CloudApi.hex(hash.digest())).put("bytes",count).put("profile_id",profile.getString("id")).put("profile_revision",profile.getInt("revision")).put("copies",1);
        runOnUiThread(()->{if(isFinishing()||isDestroyed()){shown.recycle();target.delete();return;}LinearLayout panel=new LinearLayout(this);panel.setPadding(16,16,16,16);panel.setOrientation(1);text(panel,st.optString("label")+"\n"+profile.optString("label")+" / contain / no crop\nDriver printable margins may differ; run a physical test.",15);ImageView image=new ImageView(this);image.setImageBitmap(shown);image.setAdjustViewBounds(true);image.setMaxHeight(700);panel.addView(image);NumberPicker copies=new NumberPicker(this);copies.setMinValue(1);copies.setMaxValue(setup.optInt("max_copies",1));panel.addView(copies);final boolean[] keep={false};AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Confirm this exact photo for printing").setView(panel).setPositiveButton("Queue Print",(d,n)->{keep[0]=true;int quantity=copies.getValue();work(()->{if(!config.get("scope").equals(scope))throw new IllegalStateException("Event changed; reopen print preview");spec.put("copies",quantity);try(PrintQueue q=new PrintQueue(this)){q.add(scope,spec,target.getPath(),new String[]{"hybrid","local","cloud"}[selectedMode]);}say("Print request saved. Same job ID is used on both routes.");runOnUiThread(this::resume);});}).setNegativeButton("Cancel",null).create();dialog.setOnDismissListener(d->{image.setImageDrawable(null);shown.recycle();if(!keep[0])target.delete();});dialog.show();});
    }
    @Override protected void onResume(){super.onResume();handler.post(refresh);}
    @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacks(refresh);io.shutdown();super.onDestroy();}
}
